/**
 * StaffDetailPage — Detail page for a single staff member.
 *
 * Displays:
 * - Profile card with name, role badge, hourly rate, active/inactive status (read-only toggle), createdAt
 * - Stats row with 4 metrics fetched in parallel via Promise.all
 * - Repair history table with status filter dropdown
 * - Loading/error/404 states
 */

import { useState, useEffect, useCallback } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Clock, Wrench, Activity, TrendingUp } from 'lucide-react'
import { fetchStaffMemberById, fetchStaffStats, fetchStaffRepairs } from '../api.js'
import type { StaffMemberDetail, StaffStats } from '../types.js'
import { formatHourlyRate } from '../types.js'
import { Switch } from '@/components/ui/switch.js'
import { Card, CardHeader, CardContent } from '@/components/ui/card.js'
import { STATUS_COLORS } from '@/features/repairs/types.js'

// ---------------------------------------------------------------------------
// Types — repair history row shape (matches API response)
// ---------------------------------------------------------------------------

interface RepairHistoryRow {
  id: string
  status: 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'
  bicycleBrand: string
  bicycleModel: string
  createdAt: number
  completedAt: number | null
}

// ---------------------------------------------------------------------------
// Status filter options — maps AC labels to API values
// ---------------------------------------------------------------------------

const STATUS_FILTER_OPTIONS = [
  { label: 'All', value: '' },
  { label: 'Completed', value: 'completed' },
  { label: 'In Progress', value: 'in_progress' },
  { label: 'Cancelled', value: 'cancelled' },
] as const

// ---------------------------------------------------------------------------
// Helpers — format values for display
// ---------------------------------------------------------------------------

function formatDate(value: number | string | Date | null): string {
  if (!value) return '—'
  const d = value instanceof Date ? value : new Date(value)
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
}

/** Format minutes as "Xh Ym" */
function formatMinutes(totalMinutes: number): string {
  const hours = Math.floor(totalMinutes / 60)
  const minutes = totalMinutes % 60
  if (hours > 0 && minutes > 0) return `${hours}h ${minutes}m`
  if (hours > 0) return `${hours}h`
  return `${minutes}m`
}

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function RoleBadge({ role }: { role: 'mechanic' | 'manager' }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        role === 'mechanic'
          ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300'
          : 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
      }`}
    >
      {role === 'mechanic' ? 'Mechanic' : 'Manager'}
    </span>
  )
}

function StatCard({
  icon: Icon,
  label,
  value,
}: {
  icon: React.ElementType
  label: string
  value: string
}) {
  return (
    <div className="flex items-center gap-3 rounded-lg border bg-card p-4">
      <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-muted">
        <Icon size={18} className="text-muted-foreground" />
      </div>
      <div className="min-w-0">
        <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">{label}</p>
        <p className="truncate text-lg font-semibold tabular-nums">{value}</p>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Main Component — Staff Detail Page
// ---------------------------------------------------------------------------

export function StaffDetailPage() {
  const { id } = useParams<{ id: string }>()!
  const navigate = useNavigate()

  // Profile state
  const [staff, setStaff] = useState<StaffMemberDetail | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Stats state
  const [stats, setStats] = useState<StaffStats | null>(null)
  const [statsLoading, setStatsLoading] = useState(true)
  const [statsError, setStatsError] = useState<string | null>(null)

  // Repair history state
  const [repairs, setRepairs] = useState<RepairHistoryRow[]>([])
  const [repairsLoading, setRepairsLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState('')

  // -----------------------------------------------------------------------
  // Data fetching — profile + stats in parallel via Promise.all
  // -----------------------------------------------------------------------

  const loadProfileAndStats = useCallback(async () => {
    if (!id) return
    setLoading(true)
    setError(null)
    setStatsLoading(true)
    setStatsError(null)

    try {
      const [profile, staffStats] = await Promise.all([
        fetchStaffMemberById(id),
        fetchStaffStats(id).catch((err) => {
          // Stats failure is non-fatal — show partial page with error message
          console.error('Failed to load stats:', err)
          return null as StaffStats | null
        }),
      ])

      setStaff(profile)
      if (staffStats) {
        setStats(staffStats)
      } else {
        setStatsError('Unable to load statistics')
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load staff member'
      setError(message)
      setStaff(null)
    } finally {
      setLoading(false)
      setStatsLoading(false)
    }
  }, [id])

  // -----------------------------------------------------------------------
  // Repair history fetching (separate from profile/stats)
  // -----------------------------------------------------------------------

  const loadRepairs = useCallback(async () => {
    if (!id) return
    setRepairsLoading(true)
    try {
      const response = await fetchStaffRepairs(id, { status: statusFilter || undefined })
      setRepairs(response.repairs as unknown as RepairHistoryRow[])
    } catch (err) {
      console.error('Failed to load repair history:', err)
      setRepairs([])
    } finally {
      setRepairsLoading(false)
    }
  }, [id, statusFilter])

  // -----------------------------------------------------------------------
  // Effects
  // -----------------------------------------------------------------------

  useEffect(() => {
    loadProfileAndStats()
  }, [loadProfileAndStats])

  useEffect(() => {
    loadRepairs()
  }, [loadRepairs])

  // -----------------------------------------------------------------------
  // Loading state — show spinner while profile loads
  // -----------------------------------------------------------------------

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    )
  }

  // -----------------------------------------------------------------------
  // Error / 404 state — staff member not found
  // -----------------------------------------------------------------------

  if (error || !staff) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <button
          onClick={() => navigate('/staff')}
          className="flex items-center gap-2 text-muted-foreground hover:text-foreground mb-4"
        >
          <ArrowLeft size={16} /> Back to staff list
        </button>
        <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error || 'Staff member not found'}
        </div>
      </div>
    )
  }

  // -----------------------------------------------------------------------
  // Render — Profile + Stats + Repair History
  // -----------------------------------------------------------------------

  return (
    <div className="p-6 max-w-4xl mx-auto space-y-6">
      {/* Header with back navigation */}
      <div className="flex items-center justify-between">
        <button
          onClick={() => navigate('/staff')}
          className="flex items-center gap-2 text-muted-foreground hover:text-foreground"
        >
          <ArrowLeft size={16} /> Back to staff list
        </button>
      </div>

      {/* Profile Card */}
      <Card>
        <CardHeader>
          <div className="flex items-start justify-between">
            <div>
              <h1 className="text-2xl font-bold tracking-tight">{staff.name}</h1>
              <div className="mt-2 flex items-center gap-3">
                <RoleBadge role={staff.role as 'mechanic' | 'manager'} />
                <span className="text-sm text-muted-foreground">
                  {formatHourlyRate(staff.hourlyRate)}
                </span>
              </div>
            </div>

            {/* Active/Inactive toggle — display-only (read-only) */}
            <div className="flex items-center gap-2">
              <Switch
                checked={staff.isActive}
                disabled={true}
                aria-label={`Status: ${staff.isActive ? 'Active' : 'Inactive'} (display only)`}
              />
              <span
                className={`text-xs font-medium ${
                  staff.isActive
                    ? 'text-emerald-600 dark:text-emerald-400'
                    : 'text-gray-400 dark:text-gray-500'
                }`}
              >
                {staff.isActive ? 'Active' : 'Inactive'}
              </span>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground">
            Joined: {formatDate(staff.createdAt)}
          </p>
        </CardContent>
      </Card>

      {/* Stats Row — 4 metrics in horizontal grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {statsLoading ? (
          // Skeleton loading state for stats
          <>
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="rounded-lg border bg-card p-4 animate-pulse">
                <div className="flex items-center gap-3">
                  <div className="h-10 w-10 rounded-full bg-muted" />
                  <div className="space-y-2 flex-1">
                    <div className="h-3 w-16 bg-muted rounded" />
                    <div className="h-5 w-24 bg-muted rounded" />
                  </div>
                </div>
              </div>
            ))}
          </>
        ) : statsError ? (
          // Stats error — show message spanning all 4 columns
          <div className="col-span-full p-4 bg-yellow-50 border border-yellow-200 rounded-lg text-sm text-yellow-700">
            {statsError}
          </div>
        ) : stats ? (
          <>
            {/* Total Hours Worked */}
            <StatCard
              icon={Clock}
              label="Hours Worked"
              value={formatMinutes(stats.totalHoursWorked)}
            />

            {/* Repairs Completed */}
            <StatCard
              icon={Wrench}
              label="Repairs Done"
              value={String(stats.completedRepairs)}
            />

            {/* Active Repairs */}
            <StatCard
              icon={Activity}
              label="Active Repairs"
              value={String(stats.activeRepairs)}
            />

            {/* Avg Repair Duration */}
            <StatCard
              icon={TrendingUp}
              label="Avg Duration"
              value={stats.avgRepairDurationMinutes != null ? formatMinutes(stats.avgRepairDurationMinutes) : 'N/A'}
            />
          </>
        ) : null}
      </div>

      {/* Repair History Table */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0">
          <h2 className="text-lg font-semibold tracking-tight">Repair History</h2>

          {/* Status filter dropdown */}
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="h-8 px-3 text-sm border rounded-md bg-background focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary"
            aria-label="Filter repairs by status"
          >
            {STATUS_FILTER_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </CardHeader>
        <CardContent>
          {repairsLoading ? (
            <div className="flex items-center justify-center py-8">
              <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
            </div>
          ) : repairs.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-8">
              No repairs found{statusFilter ? ` for status "${STATUS_FILTER_OPTIONS.find((o) => o.value === statusFilter)?.label}"` : ''}.
            </p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="px-3 py-2 text-left font-semibold text-muted-foreground">#</th>
                    <th className="px-3 py-2 text-left font-semibold text-muted-foreground">Bicycle</th>
                    <th className="px-3 py-2 text-left font-semibold text-muted-foreground">Status</th>
                    <th className="px-3 py-2 text-left font-semibold text-muted-foreground">Assigned</th>
                    <th className="px-3 py-2 text-left font-semibold text-muted-foreground">Completed</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {repairs.map((repair) => (
                    <tr key={repair.id} className="hover:bg-muted/30 transition-colors">
                      <td className="px-3 py-2 font-mono text-xs text-muted-foreground">
                        #{repair.id.slice(0, 8)}
                      </td>
                      <td className="px-3 py-2">
                        {repair.bicycleBrand} {repair.bicycleModel}
                      </td>
                      <td className="px-3 py-2">
                        <span
                          className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
                            STATUS_COLORS[repair.status] ?? 'bg-gray-100 text-gray-800'
                          }`}
                        >
                          {repair.status.replace('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase())}
                        </span>
                      </td>
                      <td className="px-3 py-2 text-muted-foreground">
                        {formatDate(repair.createdAt)}
                      </td>
                      <td className="px-3 py-2 text-muted-foreground">
                        {repair.completedAt ? formatDate(repair.completedAt) : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>

              {/* Showing note if many repairs */}
              {repairs.length > 50 && (
                <p className="text-xs text-muted-foreground mt-3 px-1">
                  Showing first {repairs.length} repairs.
                </p>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

/**
 * Staff — API client functions.
 */

import type { StaffMemberDetail, StaffPaginatedResponse, StaffStats } from './types.js'

const BASE_URL = '' // relative to current origin

// ---------------------------------------------------------------------------
// Management List (paginated + searchable)
// ---------------------------------------------------------------------------

export async function fetchStaffMembers({
  search,
  page = 1,
  pageSize = 25,
}: {
  search?: string
  page?: number
  pageSize?: number
}): Promise<StaffPaginatedResponse> {
  const params = new URLSearchParams()

  if (search !== undefined && search !== '') {
    params.set('search', search)
  }
  params.set('page', String(page))
  params.set('pageSize', String(pageSize))

  const response = await fetch(`${BASE_URL}/api/users?${params}`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load staff members: ${response.status}`)
  }

  return response.json() as Promise<StaffPaginatedResponse>
}

// ---------------------------------------------------------------------------
// Create Staff Member
// ---------------------------------------------------------------------------

export async function createStaffMember(data: Record<string, unknown>): Promise<StaffMemberDetail> {
  const response = await fetch(`${BASE_URL}/api/users`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  })

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to create staff member: ${response.status}`)
  }

  return response.json() as Promise<StaffMemberDetail>
}

// ---------------------------------------------------------------------------
// Update Staff Member (partial update via PATCH)
// ---------------------------------------------------------------------------

export async function updateStaffMember(
  id: string,
  data: Record<string, unknown>,
): Promise<StaffMemberDetail> {
  const response = await fetch(`${BASE_URL}/api/users/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  })

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to update staff member: ${response.status}`)
  }

  return response.json() as Promise<StaffMemberDetail>
}

// ---------------------------------------------------------------------------
// Get Single Staff Member — GET /users/:id
// ---------------------------------------------------------------------------

export async function fetchStaffMemberById(id: string): Promise<StaffMemberDetail> {
  const response = await fetch(`${BASE_URL}/api/users/${id}`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load staff member: ${response.status}`)
  }

  return response.json() as Promise<StaffMemberDetail>
}

// ---------------------------------------------------------------------------
// Staff Stats — GET /users/:id/stats
// ---------------------------------------------------------------------------

export async function fetchStaffStats(id: string): Promise<StaffStats> {
  const response = await fetch(`${BASE_URL}/api/users/${id}/stats`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load staff stats: ${response.status}`)
  }

  return response.json() as Promise<StaffStats>
}

// ---------------------------------------------------------------------------
// Repair History — GET /repairs?assignedTo=...
// ---------------------------------------------------------------------------

export interface StaffRepair {
  id: string
  status: 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'
  bicycleBrand: string
  bicycleModel: string
  createdAt: number
  completedAt: number | null
}

export interface StaffRepairHistoryResponse {
  repairs: StaffRepair[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

/** Fetch repair history for a staff member with optional status filter. */
export async function fetchStaffRepairs(
  userId: string,
  filters?: { status?: string },
): Promise<StaffRepairHistoryResponse> {
  const params = new URLSearchParams()
  params.set('assignedTo', userId)
  params.set('page', '1')
  // Fetch all repairs (no pagination limit for detail page — use large pageSize)
  params.set('pageSize', '200')

  if (filters?.status) {
    params.set('status', filters.status)
  }

  const response = await fetch(`${BASE_URL}/api/repairs?${params}`)

  if (!response.ok) {
    throw new Error(`Failed to load repair history: ${response.status}`)
  }

  return response.json() as Promise<StaffRepairHistoryResponse>
}

/**
 * StaffListPage — Management list page for staff members.
 *
 * Displays a searchable, paginated DataTable with columns for:
 * - Name (clickable to navigate to detail page)
 * - Role badge (Mechanic/Manager)
 * - Hourly rate (displayed as currency €X.XX/h)
 * - Active status toggle switch (click to toggle without opening dialog)
 *
 * Inactive staff members are visually distinguished with muted styling.
 */

import { useState, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import toast from 'react-hot-toast'
import { Pencil } from 'lucide-react'
import { useStaffMembers } from '../hooks/useStaffMembers.js'
import type { StaffMemberDetail } from '../types.js'
import { formatHourlyRate } from '../types.js'
import { updateStaffMember } from '../api.js'
import {
  DataTable,
  type DataTableColumn,
} from '@/components/ui/DataTable.js'
import { Button } from '@/components/ui/button.js'
import { Switch } from '@/components/ui/switch.js'
import { StaffFormDialog } from './StaffFormDialog.js'

// ---------------------------------------------------------------------------
// Column Cell Components
// ---------------------------------------------------------------------------

function RoleBadge({ role }: { role: 'mechanic' | 'manager' }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        role === 'mechanic'
          ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300'
          : 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
      }`}
    >
      {role === 'mechanic' ? 'Mechanic' : 'Manager'}
    </span>
  )
}

function ActiveToggle({
  isActive,
  onToggle,
}: {
  isActive: boolean
  onToggle: () => void
}) {
  return (
    <div className="flex items-center gap-2">
      <Switch
        checked={isActive}
        onCheckedChange={() => onToggle()}
        aria-label={`Toggle active status — currently ${isActive ? 'active' : 'inactive'}`}
      />
      <span
        className={`text-xs font-medium ${
          isActive
            ? 'text-emerald-600 dark:text-emerald-400'
            : 'text-gray-400 dark:text-gray-500'
        }`}
      >
        {isActive ? 'Active' : 'Inactive'}
      </span>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Page Component
// ---------------------------------------------------------------------------

export function StaffListPage() {
  const navigate = useNavigate()
  const [dialogOpen, setDialogOpen] = useState(false)
  // Track which staff member is being edited (null = create mode)
  const [editingStaff, setEditingStaff] = useState<{
    id: string
    name: string
    role: 'mechanic' | 'manager'
    hourlyRateCents: number
  } | null>(null)

  const {
    staffMembers,
    totalItems,
    currentPage,
    pageSize,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  } = useStaffMembers()

  // -----------------------------------------------------------------------
  // Handlers
  // ---------------------------------------------------------------------------

  const handleNavigateToDetail = useCallback((staffId: string) => {
    navigate(`/staff/${staffId}`)
  }, [navigate])

  const handleOpenEditDialog = useCallback((e: React.MouseEvent, staff: StaffMemberDetail) => {
    e.stopPropagation()
    setEditingStaff({
      id: staff.id,
      name: staff.name,
      role: staff.role as 'mechanic' | 'manager',
      hourlyRateCents: staff.hourlyRate,
    })
    setDialogOpen(true)
  }, [])

  const handleToggleActive = useCallback(async (staff: StaffMemberDetail) => {
    try {
      await updateStaffMember(staff.id, { isActive: !staff.isActive })
      toast.success(
        `${staff.name} is now ${!staff.isActive ? 'active' : 'inactive'}`
      )
      refresh()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update status'
      toast.error(message)
    }
  }, [refresh])

  const handleDialogClose = useCallback((open: boolean) => {
    setDialogOpen(open)
    if (!open) {
      setEditingStaff(null)
    }
  }, [])

  const handleSaveSuccess = useCallback(() => {
    toast.success(
      editingStaff ? 'Staff member updated successfully' : 'Staff member created successfully'
    )
    refresh()
  }, [editingStaff, refresh])

  // -----------------------------------------------------------------------
  // Column definitions for DataTable
  // ---------------------------------------------------------------------------

  const columns: DataTableColumn<StaffMemberDetail>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (staff: StaffMemberDetail) => (
        <div className="flex items-center gap-2">
          <span
            className="font-medium cursor-pointer hover:underline underline-offset-2"
            onClick={() => handleNavigateToDetail(staff.id)}
            title="Click to view details"
          >
            {staff.name}
          </span>
          <button
            onClick={(e) => handleOpenEditDialog(e, staff)}
            className="text-muted-foreground hover:text-foreground transition-colors"
            title="Edit staff member"
            aria-label={`Edit ${staff.name}`}
          >
            <Pencil size={14} />
          </button>
        </div>
      ),
    },
    {
      key: 'role',
      header: 'Role',
      render: (staff: StaffMemberDetail) => (
        <RoleBadge role={staff.role as 'mechanic' | 'manager'} />
      ),
    },
    {
      key: 'hourlyRate',
      header: 'Hourly Rate',
      render: (staff: StaffMemberDetail) => (
        <span>{formatHourlyRate(staff.hourlyRate)}</span>
      ),
    },
    {
      key: 'isActive',
      header: 'Status',
      render: (staff: StaffMemberDetail) => (
        <ActiveToggle
          isActive={staff.isActive}
          onToggle={() => handleToggleActive(staff)}
        />
      ),
    },
  ]

  // -----------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Staff Members</h1>
          <p className="text-muted-foreground mt-1">
            View and manage your team roster. Click a name to view details, or use the pencil icon to edit.
          </p>
        </div>
        <Button onClick={() => { setEditingStaff(null); setDialogOpen(true); }}>
          New Staff Member
        </Button>
      </div>

      {/* Error banner */}
      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
          <p className="font-medium">Error loading staff members</p>
          <p>{error}</p>
          <Button variant="outline" size="sm" onClick={refresh} className="mt-2">
            Retry
          </Button>
        </div>
      )}

      {/* DataTable */}
      <DataTable<StaffMemberDetail>
        data={staffMembers}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={goToPage}
        isLoading={isLoading}
        emptyMessage="No staff members found"
        rowClassName={(staff) =>
          !staff.isActive
            ? 'opacity-50 bg-muted/10 hover:bg-muted/20'
            : ''
        }
      />

      {/* Staff Form Dialog — create or edit mode */}
      <StaffFormDialog
        open={dialogOpen}
        onOpenChange={handleDialogClose}
        onSaveSuccess={handleSaveSuccess}
        initialData={editingStaff ?? undefined}
      />
    </div>
  )
}

/**
 * Staff — Frontend types.
 */

// ---------------------------------------------------------------------------
// Re-export shared domain types
// ---------------------------------------------------------------------------

export type { StaffMember, NewStaffMember, UpdateStaffMember, StaffStats } from '@shared/types/staff.js'

// ---------------------------------------------------------------------------
// Frontend DTOs (mirroring backend response shapes)
// ---------------------------------------------------------------------------

/** Full staff member detail returned by the paginated list endpoint. */
export interface StaffMemberDetail {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date | string
  // Index signature required by DataTable<T extends Record<string, unknown>>
  [key: string]: unknown
}

/** Paginated response from the staff management list endpoint. */
export interface StaffPaginatedResponse {
  users: StaffMemberDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Display helpers
// ---------------------------------------------------------------------------

/** Format hourly rate (cents) as currency string with /h suffix. */
export function formatHourlyRate(cents: number): string {
  const euros = cents / 100
  return `€${euros.toFixed(2)}/h`
}
